-- 0011_add_work_action — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- action: one thing someone has to do, by a date (E5 AC1; SOP-DEL-03 "every action gets an owner and a
-- date, including your own"). Staff see all rows; a client sees its own rows marked visibility = 'client';
-- partners see nothing until a policy links rows to their assigned jobs.
CREATE TABLE action (
  id           uuid PRIMARY KEY,
  client_id    uuid NOT NULL,
  -- What the action is about. Only the project (site) exists today; case and visit links are added with
  -- their tables (E5.3, E6), and the action_linked check then lists them too.
  site_id      uuid,
  title        text NOT NULL CHECK (btrim(title) <> ''),
  -- The owner is an OCS user, or a named person outside OCS (client, third party) — never nobody.
  owner_id     uuid,
  owner_name   text CHECK (btrim(owner_name) <> ''),
  due          date NOT NULL,
  status       text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'done', 'cancelled')),
  done_at      timestamptz,
  -- Where it came from (E5 AC1): every item in the feed shows its source (AC4).
  source_kind  text NOT NULL CHECK (source_kind IN
                 ('manual', 'mail', 'dingtalk', 'meeting', 'visit', 'alert', 'comment')),
  source_ref   text,
  visibility   text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  created_by   uuid NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  archived_at  timestamptz,
  CONSTRAINT action_linked CHECK (num_nonnulls(site_id) >= 1),
  CONSTRAINT action_owner CHECK (num_nonnulls(owner_id, owner_name) = 1),
  CONSTRAINT action_done CHECK ((status = 'done') = (done_at IS NOT NULL)),
  FOREIGN KEY (site_id, client_id) REFERENCES site (id, client_id)
);
CREATE INDEX action_client ON action (client_id);
CREATE INDEX action_site ON action (site_id);
-- "My actions" and overdue alerts read open actions by owner and due date.
CREATE INDEX action_open_owner ON action (owner_id, due) WHERE status IN ('open', 'in_progress');

ALTER TABLE action ENABLE ROW LEVEL SECURITY;
CREATE POLICY action_internal ON action FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY action_client_read ON action FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON action TO ocs_app;
